// Detect credential stuffing: many failed logins from one IP targeting multiple accounts
// Threshold: 10+ failures across 5+ distinct user_ids within 300 seconds
const ip = $input.first().json.source_ip;
const userId = $input.first().json.user_id || '__unknown__';
const now = Date.now();
const windowMs = 300 * 1000;
const failureThreshold = 10;
const distinctUserThreshold = 5;

const staticData = $getWorkflowStaticData('global');
if (!staticData.credStuffing) staticData.credStuffing = {};
if (!staticData.credStuffing[ip]) staticData.credStuffing[ip] = { events: [], users: {} };

const state = staticData.credStuffing[ip];

// Prune old events
state.events = state.events.filter(e => now - e.ts < windowMs);

// Prune old user entries
for (const uid of Object.keys(state.users)) {
  state.users[uid] = state.users[uid].filter(ts => now - ts < windowMs);
  if (state.users[uid].length === 0) delete state.users[uid];
}

// Record this event
state.events.push({ ts: now, userId });
if (!state.users[userId]) state.users[userId] = [];
state.users[userId].push(now);

const failureCount = state.events.length;
const distinctUsers = Object.keys(state.users).length;
const suspicious = failureCount >= failureThreshold && distinctUsers >= distinctUserThreshold;

return [{
  json: {
    source_ip: ip,
    failure_count: failureCount,
    distinct_users: distinctUsers,
    suspicious,
    failure_threshold: failureThreshold,
    distinct_user_threshold: distinctUserThreshold,
    window_seconds: 300
  }
}];
